"""Uniform integer normalization of complete generated compact stair sprites."""
import argparse,json,math
from pathlib import Path
from PIL import Image
import catalog
ROOT=Path(__file__).resolve().parents[1]
PROMPTS={
'up': 'A single tiny indoor ascending staircase game tile in Pokémon Emerald / FireRed GBA pixel art. Intended logical size EXACTLY 16 by 16 pixels, enlarged with clean hard square pixel clusters, just six restrained native GBA colors. Three-quarter top-down RPG view, stairs ascending toward the upper right: complete diagonal charcoal-gray stair side edge and pale gray stair treads, with a thin dark handrail along the upper diagonal edge. Three or four broad visible treads. Every tread and both ends fit completely within one square 16x16 tile. A compact stair entrance marker designed for the original Game Boy Johto indoor footprint. No large surrounding platform or wall, no text or labels, no glow or gradients, no perspective vanishing point, no border. Truly transparent background outside the single complete compact staircase.',
'down': 'A single tiny descending staircase entrance tile for a top-down Pokémon Emerald / FireRed GBA RPG interior, logical resolution EXACTLY16 by16 pixels, shown enlarged as clean hard square pixel clusters. Entire square small stairwell opening with dark gray descending steps receding toward the upper right, a complete thin pale gray diagonal side railing, all edges and treads contained inside one16x16 tile. Restrained6-color gray and blue-gray GBA palette, crisp large pixel clusters. This is stairs DOWN, a little dark stairwell opening seen from above, not a ladder and not a door. Truly transparent background outside the complete compact staircase object, no room or platform, no glow, no text, no labels, no gradient.'}
def main():
 p=argparse.ArgumentParser();p.add_argument('kind',choices=PROMPTS);p.add_argument('source',type=Path);a=p.parse_args();im=Image.open(a.source).convert('RGBA');im.putalpha(im.getchannel('A').point(lambda v:255 if v>=128 else 0));b=im.getbbox();factor=math.ceil(max(b[2]-b[0],b[3]-b[1])/16);left=(b[0]+b[2])//2-8*factor;box=(left,b[3]-16*factor,left+16*factor,b[3]);assert box[0]<=b[0]and box[1]<=b[1]and box[2]>=b[2];tile=im.crop(box).resize((16,16),Image.Resampling.NEAREST).quantize(colors=12,method=Image.Quantize.FASTOCTREE,dither=Image.Dither.NONE).convert('RGBA');tile.putalpha(tile.getchannel('A').point(lambda v:255 if v>=128 else 0));folder=ROOT/'assets/original/interior-stairs';folder.mkdir(exist_ok=True,parents=True);path=folder/(a.kind+'.png');tile.save(path);proof={'origin':'Original complete compact Gen3 interior '+a.kind+' staircase.','tool':'image_gen.imagegen','prompt':PROMPTS[a.kind],'source_file':a.source.name,'source_sha256':catalog.sha(a.source.read_bytes()),'source_size':im.size,'visible_bounds':b,'crop':box,'integer_reduction':factor,'final_size':[16,16],'binary_alpha':128,'palette_colors':12,'dither':False,'whole_staircase_preserved':True,'files':{path.name:catalog.sha(path.read_bytes())}};(folder/(a.kind+'-provenance.json')).write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps(proof))
if __name__=='__main__':main()
